import {router} from './router.js';import {initAmbient} from '../effects/ambient.js';import {initInteractions} from '../effects/interactions.js';import {initKeyboard} from '../accessibility/keyboard.js';import {characterDirector} from '../characters/director.js';import {on} from '../utils/events.js';export function boot(){initAmbient();initInteractions();initKeyboard();characterDirector.init();on('state',()=>router.start());on('toast',e=>window.dispatchEvent(new CustomEvent('forge:ui-toast',{detail:e.detail})));router.start()}
